const getTranslation=(locale:Locale,key:TranslationKey)=>key in translations[locale]?translations[locale][key as BaseTranslationKey]:key in loginTranslations[locale]?loginTranslations[locale][key as LoginTranslationKey]:key in settingsTranslations[locale]?settingsTranslations[locale][key as SettingsTranslationKey]:key in plannerTranslations[locale]?plannerTranslations[locale][key as PlannerTranslationKey]:key in workspaceTranslations[locale]?workspaceTranslations[locale][key as WorkspaceTranslationKey]:key in inventoryTranslations[locale]?inventoryTranslations[locale][key as InventoryTranslationKey]:roadtripTranslations[locale][key as RoadtripTranslationKey];
const LocaleContext=createContext<LocaleContextValue>({locale:"vi",t:(key,values)=>interpolate(getTranslation("vi",key),values)});

export function LocaleProvider({children}:{children:ReactNode}){
  const [locale,setLocale]=useState<Locale>("vi");
  useEffect(()=>{
    const apply=(value:unknown)=>{const next=normalizeLocale(value);setLocale(next);document.documentElement.lang=next;document.documentElement.dir=["ar","he"].includes(next)?"rtl":"ltr"};
    const update=()=>{try{apply(JSON.parse(localStorage.getItem("travel_preferences")||"{}").ngon_ngu||"vi")}catch{apply("vi")}};
    const sync=(event:StorageEvent)=>{if(event.key===null||event.key==="travel_preferences")update()};
    update();window.addEventListener("travel-preferences-changed",update);window.addEventListener("storage",sync);return()=>{window.removeEventListener("travel-preferences-changed",update);window.removeEventListener("storage",sync)};
  },[]);
  const t:Translate=useCallback((key:TranslationKey,values:Record<string,string|number>={})=>{
    return interpolate(getTranslation(locale,key),values);
  },[locale]);
  return <LocaleContext.Provider value={{locale,t}}>{children}</LocaleContext.Provider>;
}

export const useLocale=()=>useContext(LocaleContext);



